// Dev tool: write Img buffers as PNG files, so the art (generated by code) can be checked by eye in Node:
//   import { writePng } from '../scripts/art-dump.js'. No dependencies: node:zlib does the compression.
import fs from 'node:fs';
import zlib from 'node:zlib';

const crcTable = new Uint32Array(256).map((_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (buf) => {
  let c = 0xffffffff;
  for (const b of buf) c = crcTable[(c ^ b) & 255] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
};
const chunk = (type, data) => {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
};

/** Encode an Img (or { w, h, data }) as PNG bytes. `scale` upsizes by an integer (nearest neighbour). `bg` fills transparency. */
export function encodePng(img, { scale = 1, bg = null } = {}) {
  const w = img.w * scale; const h = img.h * scale;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) {
    raw[y * (w * 4 + 1)] = 0;
    for (let x = 0; x < w; x++) {
      const si = (((y / scale) | 0) * img.w + ((x / scale) | 0)) * 4;
      const o = y * (w * 4 + 1) + 1 + x * 4;
      let [r, g, b, a] = [img.data[si], img.data[si + 1], img.data[si + 2], img.data[si + 3]];
      if (bg && a < 255) { const t = a / 255; r = Math.round(r * t + bg[0] * (1 - t)); g = Math.round(g * t + bg[1] * (1 - t)); b = Math.round(b * t + bg[2] * (1 - t)); a = 255; }
      raw[o] = r; raw[o + 1] = g; raw[o + 2] = b; raw[o + 3] = a;
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6;
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]);
}

export function writePng(file, img, opts = {}) {
  fs.writeFileSync(file, encodePng(img, opts));
  return file;
}
